import React, { useState, useEffect } from "react";

function YoutubeAPI() {
	const [youtubeData, setYoutubeData] = useState([]);
	const [loading, setLoading] = useState(true);

	const API_KEY =
		process.env.REACT_APP_YOUTUBE_API_KEY ||
		"AIzaSyCpTF_yLNSD38RsC4Q8fszQZCJNZ6F8Kvc";
	const CHANNEL_ID =
		process.env.REACT_APP_YOUTUBE_CHANNEL_ID || "UCYFQ33UIPERYx8-ZHucZbDA";
	const MAX_RESULTS = 6;

	useEffect(() => {
		const fetchVideos = async () => {
			try {
				const res = await fetch(
					`https://www.googleapis.com/youtube/v3/search?key=${API_KEY}&channelId=${CHANNEL_ID}&part=snippet,id&order=date&maxResults=${MAX_RESULTS}`,
				);
				const data = await res.json();
				if (data.items && data.items.length > 0) {
					setYoutubeData(data.items);
				} else {
					console.warn("YouTube API returned no items, using fallback", data);
				}
			} catch (error) {
				console.error("Error fetching YouTube data:", error);
			} finally {
				setLoading(false);
			}
		};

		fetchVideos();
	}, [API_KEY, CHANNEL_ID]);

	return (
		<div className="allVideosWrapper pb-5">
			<div className="container">
				<div className="row justify-content-center text-center">
					<div className="col-12 mt-5 mb-4">
						<div className="title-wrapper bold" style={{ fontSize: "36px", fontWeight: "700" }}>
							Latest Videos
						</div>
					</div>

					{loading && <div className="col-12 text-center py-4">Loading videos...</div>}

					{youtubeData?.map((singleVideo, i) => {
						const vidId = singleVideo.id?.videoId;
						const snippet = singleVideo.snippet;
						if (!vidId || !snippet) return null;

						const videoLink = `https://www.youtube.com/watch?v=${vidId}`;
						const thumbUrl =
							snippet.thumbnails?.high?.url ||
							snippet.thumbnails?.medium?.url ||
							snippet.thumbnails?.default?.url;

						return (
							<div key={vidId || i} className="col-sm-12 col-md-6 col-lg-4 mb-4 text-start">
								<div className="singleVideoWrapper h-100 p-2 d-flex flex-column">
									<div className="videoThumbnail mb-2">
										<a href={videoLink} target="_blank" rel="noopener noreferrer">
											<img
												src={thumbUrl}
												alt={snippet.title}
												className="img-fluid rounded shadow-sm w-100"
												style={{ objectFit: "cover", height: "200px" }}
											/>
										</a>
									</div>
									<div className="videoInfo mt-2">
										<div className="videoTitle mb-2">
											<a
												href={videoLink}
												target="_blank"
												rel="noopener noreferrer"
												style={{
													color: "#0071e3",
													textDecoration: "none",
													fontSize: "14px",
													fontWeight: "600",
													lineHeight: "1.4",
													display: "-webkit-box",
													WebkitLineClamp: 2,
													WebkitBoxOrient: "vertical",
													overflow: "hidden",
												}}
											>
												{snippet.title}
											</a>
										</div>
										<div
											className="videoDesc text-secondary"
											style={{
												fontSize: "13px",
												lineHeight: "1.4",
												display: "-webkit-box",
												WebkitLineClamp: 3,
												WebkitBoxOrient: "vertical",
												overflow: "hidden",
											}}
										>
											{snippet.description}
										</div>
									</div>
								</div>
							</div>
						);
					})}
				</div>
			</div>
		</div>
	);
}

export default YoutubeAPI;
